function minReach(houses: number[], heaters: number[]): number {
  let need = 0;
  for (const h of houses) {
    let nearest = Infinity;
    for (const t of heaters) nearest = Math.min(nearest, Math.abs(h - t));
    need = Math.max(need, nearest);
  }
  return need;
}

