function minReach(houses: number[], heaters: number[]): number {
  const hs = heaters.slice().sort((a, b) => a - b);
  let need = 0;
  for (const h of houses) {
    let lo = 0, hi = hs.length; // first index with hs[i] >= h
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (hs[mid] < h) lo = mid + 1;
      else hi = mid;
    }
    let nearest = Infinity;
    if (lo < hs.length) nearest = hs[lo] - h;
    if (lo > 0) nearest = Math.min(nearest, h - hs[lo - 1]);
    need = Math.max(need, nearest);
  }
  return need;
}

