function minReach(houses: number[], heaters: number[]): number {
  const hs = houses.slice().sort((a, b) => a - b);
  const ts = heaters.slice().sort((a, b) => a - b);
  let j = 0, need = 0;
  for (const h of hs) {
    // advance while the next heater is at least as close
    while (j + 1 < ts.length && Math.abs(ts[j + 1] - h) <= Math.abs(ts[j] - h)) j++;
    need = Math.max(need, Math.abs(ts[j] - h));
  }
  return need;
}

